.darma-loader-darma-b8-magnifier-search { --accent: var(--loader-color, #64748b); --accent-2: var(--loader-secondary-color, #38bdf8); width: var(--loader-size, 80px); height: var(--loader-size, 80px); position: relative; }
.darma-loader-darma-b8-magnifier-search span { position: absolute; left: 50%; top: 50%; width: calc(var(--loader-size, 80px) * .4); height: calc(var(--loader-size, 80px) * .4); margin: calc(var(--loader-size, 80px) * -.2) 0 0 calc(var(--loader-size, 80px) * -.2); border: calc(var(--loader-size, 80px) * .06) solid var(--accent); border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, var(--accent-2) 18%, transparent), transparent 70%); animation: darma-loader-darma-b8-magnifier-search-search calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b8-magnifier-search span::after { content: ''; position: absolute; right: calc(var(--loader-size, 80px) * -.13); bottom: calc(var(--loader-size, 80px) * -.07); width: calc(var(--loader-size, 80px) * .2); height: calc(var(--loader-size, 80px) * .07); border-radius: 4px; background: var(--accent); transform: rotate(45deg); transform-origin: left center; }
@keyframes darma-loader-darma-b8-magnifier-search-search { 0%, 100% { transform: translate(-42%, -40%); } 25% { transform: translate(12%, -32%); } 50% { transform: translate(22%, 20%); } 75% { transform: translate(-30%, 12%); } }

